<fieldset class="contact-settings"><legend>ช่องทางติดต่อ / Contact Us</legend>
<p>แสดงเฉพาะช่องทางที่กรอกข้อมูล <a href="<?= base_url() ?>contactus" target="_blank" rel="noopener">ดูหน้าติดต่อเรา ↗</a></p>
<?php foreach (contact_social_fields() as $key=>$label): ?>
<label>ลิงก์ <?= e($label) ?><input type="url" name="<?= e($key) ?>" maxlength="2000" placeholder="<?= $key==='line_url' ? 'https://lin.ee/...' : ($key==='messenger_url' ? 'https://m.me/...' : 'https://...') ?>" value="<?= e($settings[$key] ?? '') ?>"></label>
<?php endforeach ?>
<small>ใช้ลิงก์ https:// เต็มรูปแบบ หากไม่ใส่ลิงก์ LINE ระบบจะใช้ LINE Official ID ด้านบน</small>
<h3>เบอร์โทรทีมขาย</h3><p>เพิ่มชื่อและเบอร์โทรของเซลส์ได้สูงสุด 20 คน ลูกค้ากดโทรจากหน้าเว็บได้ทันที</p>
<div id="contact-sales-rows">
<?php $salesRows=json_decode($settings['contact_sales'] ?? '[]',true); if (!is_array($salesRows) || !$salesRows) $salesRows=[['name'=>'','phone'=>'']]; foreach ($salesRows as $person): ?>
<div class="contact-sales-row"><label>ชื่อเซลส์<input name="sales_name[]" maxlength="100" value="<?= e($person['name']) ?>" placeholder="เช่น คุณเมย์"></label><label>เบอร์โทร<input name="sales_phone[]" type="tel" maxlength="30" value="<?= e($person['phone']) ?>" placeholder="081-234-5678"></label><button type="button" class="text-button" data-remove-sales>ลบ</button></div>
<?php endforeach ?></div>
<button type="button" class="btn secondary" id="add-contact-sales">+ เพิ่มเซลส์</button>
<label>วันและเวลาทำการ<textarea name="contact_hours" rows="4" maxlength="1000" placeholder="จันทร์–ศุกร์ 09:00–18:00 น.&#10;เสาร์ 09:00–13:00 น.&#10;หยุดวันอาทิตย์และวันหยุดนักขัตฤกษ์"><?= e($settings['contact_hours'] ?? '') ?></textarea><small>ใส่ได้หลายบรรทัด รวมวันหยุดหรือเวลาตอบแชต</small></label>
<label>ที่อยู่ติดต่อ<textarea name="company_address" rows="3" maxlength="1000"><?= e($settings['company_address'] ?? '') ?></textarea><small>ใช้ข้อมูลเดียวกับที่อยู่บริษัทในเอกสารเรียกเก็บเงิน</small></label>
<label>Google Maps — ลิงก์ฝังแผนที่ / โค้ด iframe<textarea name="contact_map_embed" rows="3" maxlength="10000" placeholder="https://www.google.com/maps/embed?pb=..."><?= e($settings['contact_map_embed'] ?? '') ?></textarea><small>ใน Google Maps เลือก แชร์ → ฝังแผนที่ → คัดลอก HTML แล้ววางได้เลย</small></label>
<label>ลิงก์เปิด Google Maps / นำทาง<input type="url" name="contact_map_url" maxlength="2000" placeholder="https://maps.app.goo.gl/..." value="<?= e($settings['contact_map_url'] ?? '') ?>"><small>ลิงก์แชร์ใช้สำหรับปุ่มนำทาง ส่วนแผนที่บนหน้าเว็บใช้ช่องฝังแผนที่ด้านบน</small></label>
</fieldset>
<style>.contact-settings{border:1px solid #ddd;border-radius:16px;padding:24px;display:grid;gap:18px;min-width:0}.contact-settings legend{font-size:20px;font-weight:700;padding:0 8px}.contact-settings p{margin:0;color:#666}.contact-sales-row{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:end;margin-bottom:12px}.contact-sales-row button{min-height:44px}.contact-settings #add-contact-sales{justify-self:start}@media(max-width:600px){.contact-settings{padding:16px}.contact-sales-row{grid-template-columns:1fr}.contact-sales-row button{justify-self:start}}</style>
<script>document.addEventListener('DOMContentLoaded',()=>{const rows=document.getElementById('contact-sales-rows'),add=document.getElementById('add-contact-sales');function sync(){add.disabled=rows.children.length>=20}add.addEventListener('click',()=>{if(rows.children.length>=20)return;const row=document.createElement('div');row.className='contact-sales-row';row.innerHTML='<label>ชื่อเซลส์<input name="sales_name[]" maxlength="100" placeholder="เช่น คุณเมย์"></label><label>เบอร์โทร<input name="sales_phone[]" type="tel" maxlength="30" placeholder="081-234-5678"></label><button type="button" class="text-button" data-remove-sales>ลบ</button>';rows.append(row);row.querySelector('input').focus();sync()});rows.addEventListener('click',event=>{if(event.target.closest('[data-remove-sales]')){event.target.closest('.contact-sales-row').remove();sync()}});sync()});</script>
